mapper.select:
SELECT b.id, a.stock_id, sum(num) as num, sum(price) as price, b.add_date, b.store_id, b.HANDLER, b.STATUS, b.supplier, b.depository_numbers, b.process_instance_id, sum(a.amount) as amount FROM consumable_stock_detail a INNER JOIN consumable_add_record b ON a.stock_id = b.id inner join consumable c on a.consumable_id=c.id
and b.business_type != 'IMPORT'
and b.add_date = #{param.addDate}
and b.status = #{param.status}
and b.store_id = #{param.storeId}
and (c.name like concat('%',#{param.keyword},'%') or c.`code` like concat('%','RK168','%') or b.depository_numbers like concat('%',#{param.keyword},'%'))
GROUP BY b.id order by b.add_date desc,b.create_time desc
